      "time": "2022-04-15 20:33:28",
      "post_content": "当时从月工袋里拿出来时以为是印上去的图案心中毫无波澜，打开座位上的色纸时心一下凉了半截，既然没拿到签名就不去想了毕竟主要还是来听憨唱歌的，于是向后排的毛怪借了一张签名拍照留念……到了最后憨问了一句：有没有在自闭站抽到签名的……我懵了，拿出月工袋里的色纸反复查看，又问了隔壁毛怪：你看这是签名还是印上去的啊？ 那一天真是从期待到失望再到激动啊。想一想在自闭站排队时如果早一个晚一个或许都无缘拿到签名了，从小生活在东北也没机会去南方玩，那时正好是我状态较差的时候，趁着辞掉工作后的这一段空档第一次来到了南方来听演唱会，这个签名可以说是对我人生的一种鼓励。加油毛怪们，未来还有无限可能，愿大家都能成为自己心中的样子。",
