      "type": "回复",
      "author": "糖炒栗子",
      "time": "2022-05-04 00:03:16",
      "post_content": "最想入一个镜头，想问一下有没有毛怪知道55－250和55－200有什么区别吗？  正在用的是18－55的，平时主要拍风光偶尔拍一些人像，预算有限，是先入这中长焦的好还是入一颗小痰盂好一些？",
