      "time": "2022-09-26 00:09:36",
      "post_content": "开盲盒是十分甚至九分的刺激，内容听主播发配是屈服于黑道千金的势力。意料中的磁带，让我脑中实验性奇怪周边的猜想就此逝去。最后我瑞思拜，向代收货代拍照的我妈发出致意。（虽然拍的有点糊）但不得不说，印到项链包装上的小白裙、人形亚克力的小白裙、疑似错把专辑封面印到色纸的小白裙，还有圆形亚克力上的新款小白裙，都是对阿伟发出的生死挑战！还有《它像一颗》的色纸也绝对真实好看！疑似没有夹子的闪毛怪发夹拿去当摆件也好办！磁带的含金量在图书的周边板块上必须有一席之地，对这份空气质量的夸赞不能只凭我一己之力……嗯？你说包装看起来是专辑，拆开却没有光盘？啊，那咱也不必干急，毕竟“空气”是理所当然~",
