      "time": "2022-10-10 01:38:24",
      "post_content": "因为处于特殊时期和节点 直播间近期会开等级禁言 但是是暂时且短期的 会逐渐根据情况调整等级并逐渐关闭 无法发送弹幕的各位还请稍稍等待几天～虽然我觉得“真诚是可以打败很多东西的武器” 但是很多事情也不是我能把握住发展方向的 我也曾因 自认为“真诚坦然”的发言翻车过 导致情况往更恶劣的方向发展所以在比较严肃的事情上 我还是决定听从指导意见 所以直播间最近发生的事情 没有办法去和大家摊开来说 也不建议大家去讨论但是请相信一切都是出于让255能陪伴大家更久的考量这几天看到许多毛怪们 在公开场合非常默契的不去聊不去问 只是一如既往聊着自己的日常/游戏 在动态跟我道早晚安 我那天发微博其实也是想暗暗告诉你们“情况很ok哦 别担心” 大家也像听懂了我的心意一样 没有询问没有慌张 只是顺着我的微博内容开起了玩笑和讨论 看到这些真的很感动很安心 我也没忍住给平台方炫耀了一下 也让他们放心了一些 谢谢你们～晚安😴～",
