      "post_content": "你们不觉得雷欧力和酷拉皮卡这对也很有意思吗！两个人从头互相损到尾，但又特别相信对方（他俩的互损不是打打闹闹那种，而是真的互相揭底）两个人现在都成了对方在前期想成为的状态，雷欧力从原来的市侩变成了现在这种真的为朋友着想，在本职工作上也尽心尽力，而酷拉皮卡却陷进了复仇的泥潭。整部番里我最喜欢的一个画面是选举片ED中的一个画面，（这个ED画面是选举篇的ED，这个时候酷拉皮卡应该是复仇最上头的时候，因为选举片结束给了酷拉皮卡坐在一堆火红眼前面的画面吗，所以我猜的）此时的雷欧力回头关心酷拉皮卡，但是一想到现在说什么酷拉皮卡都不会听就低头叹了口气。而且按照正常人思维判断，雷欧力是主角团最近接正常人的一个人！第一次看猎人的时候我对雷欧力的印象一直是个配角，到现在重温一遍之后发现这个团队没有雷欧力是真的不行，希望在黑暗大陆篇雷欧力和酷拉皮卡也能有一个好的故事吧",
